function plan(run){if(run.experienceVersion===3)return quickPlan(run);const schedule=run.schedule||DEFAULT_SCHEDULE;const used=Object.values(schedule).reduce((n,v)=>n+v,0);return `<section class="journey-plan"><p class="eyebrow">ПРОБУЖДЕНИЕ · ПОСМОТРИ НА СВОЙ ДЕНЬ</p><h1>Куда уходят твои 24 часа?</h1><p class="game-lead">Нажимай + и −. Покажи обычный день, а не идеальный. Сон, отдых и время семьи здесь не нужно сокращать.</p><form id="game-plan-form"><div class="plan-layout"><div class="day-dial"><div class="day-ring" id="day-ring" style="background:${ringGradient(schedule)}" role="img" aria-label="Распределение 24 часов"><div><small>РАСПРЕДЕЛЕНО</small><strong id="day-used">${fmt(used)}</strong><span>из 24 ч</span></div></div><output id="game-budget-preview" aria-live="polite">Не учтено ${fmt(1440-used)}</output><p>Нераспределенное время остается неучтенным. Только «Проверенный резерв» доступен для игровых решений.</p></div><div class="activity-list">${DAY_ACTIVITIES.map(([key,label,icon])=>`<div class="activity-row"><div class="activity-label"><span aria-hidden="true">${icon}</span><strong>${label}</strong></div><div class="time-stepper"><button type="button" data-game="adjust-time" data-key="${key}" data-delta="-15" aria-label="Уменьшить ${label.toLowerCase()} на 15 минут">−</button><output data-time-output="${key}">${fmt(schedule[key]||0)}</output><button type="button" data-game="adjust-time" data-key="${key}" data-delta="15" aria-label="Увеличить ${label.toLowerCase()} на 15 минут">+</button></div><input type="hidden" name="${key}" value="${schedule[key]||0}"></div>`).join('')}</div></div><p id="game-form-error" role="alert"></p><button class="primary game-cta">ВЫБРАТЬ МОЕ ЖЕЛАНИЕ →</button></form></section>`;}
